// Supabase Send SMS hook (Standard Webhooks). Verify the signature, then hand phone + code to WhatsApp.
// Paste the hook secret Supabase shows (v1,whsec_...) between the quotes below.
const HOOK_SECRET = '';
const crypto = require('crypto');
const item = $input.first();
const h = item.json.headers || {};
const id = h['webhook-id'] || '', ts = h['webhook-timestamp'] || '', sigs = String(h['webhook-signature'] || '');
let raw = '';
try { if (item.binary && item.binary.data) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) {}
if (!raw) raw = JSON.stringify(item.json.body || {});
const out = (ok, extra) => [{ json: Object.assign({ ok }, extra) }];
if (!HOOK_SECRET) return out(false, { reason: 'hook secret not set' });
const age = Math.abs(Date.now() / 1000 - Number(ts));
if (!id || !ts || !(age < 300)) return out(false, { reason: 'stale or missing headers' });
const key = Buffer.from(HOOK_SECRET.replace(/^v1,/, '').replace(/^whsec_/, ''), 'base64');
const expected = crypto.createHmac('sha256', key).update(id + '.' + ts + '.' + raw).digest('base64');
const good = sigs.split(' ').some(s => { const v = s.split(',')[1] || ''; return v.length === expected.length && crypto.timingSafeEqual(Buffer.from(v), Buffer.from(expected)); });
if (!good) return out(false, { reason: 'bad signature' });
let body = {};
try { body = JSON.parse(raw); } catch (e) { body = item.json.body || {}; }
const phone = String((body.user && body.user.phone) || '').replace(/\D/g, '');
const otp = String((body.sms && body.sms.otp) || '').replace(/\D/g, '');
if (!phone || !otp) return out(false, { reason: 'missing phone or code' });
return out(true, { phone, otp, text: 'كود الدخول لمركز التحكم: ' + otp + '\nصالح ٥ دقايق. متقولوش لحد، حتى لو حد من الشركة طلبه.' });
